export const blocks: readonly LiturgyBlock[] = [
  {"id": "cu-sv--0001", "section": "service", "who": "rubric", "text": "Святых, славных и всехвальных первоверховных апостолов петра и павла"},
  {"id": "cu-sv--0002", "section": "service", "who": "reader", "text": "НА МАЛОЙ ВЕЧЕРНИ На"},
  {"id": "cu-sv--0003", "section": "service", "who": "reader", "text": "Господи, воззвах:"},
  {"id": "cu-sv--0004", "section": "service", "who": "rubric", "text": "стихиры на 4, глас 4."},
  {"id": "cu-sv--0005", "section": "service", "who": "reader", "text": "Подобен: Дал еси знамение:"},
  {"id": "cu-sv--0006", "section": "service", "who": "reader", "text": "Дал еси хваление Церкви Твоей, Господи, / честныя апостолы Твоя, / в нейже просиявают мысленнии светильницы, / Петр же и Павел, якоже звезды словесныя, / вселенную озаряюще, / имиже просветил еси западный мрак, / Иисусе Всесильне, / Спасе душ наших."},
  {"id": "cu-sv--0007", "section": "service", "who": "reader", "text": "Дал еси утверждение Церкви Твоей, Господи, / Петрову твердость, и Павлов разум, / и светлую мудрость, / и обоих богогласие истинное, / еллинскую прелесть отгонящее, / темже, тайноводими от обоих, / поем Тя, Иисусе Всесильне, / Спасе душ наших."},
  {"id": "cu-sv--0008", "section": "service", "who": "reader", "text": "Дал еси образ обращения согрешающим, / оба апостолы Твоя, / оваго убо отвергшагося Тебе во время страсти и покаявшася, / оваго же проповеди Твоей сопротивляющася и веровавша, / и обою собору первостоятельствующих другов Твоих, / Иисусе Всесильне, / Спасе душ наших."},
  {"id": "cu-sv--0009", "section": "service", "who": "reader", "text": "Слава, глас 8. Иоанна монаха: Досадитель и гонитель Церкве был еси, / Павле всеблаженне, / с Небесе же зван быв, защитил еси сию преславно, / ейже ныне моли избавитися от бед / и спастися душам нашим."},
  {"id": "cu-sv--0010", "section": "service", "who": "reader", "text": "И ныне, Богородичен: Кров Твой, Богородице Дево, / врачевство есть духовное: / в онь бо прибегающе, / от душевных недуг избавляемся. Прокимен дне."},
  {"id": "cu-sv--0011", "section": "service", "who": "reader", "text": "На стиховне стихиры, глас 2. Подобен: Егда от Древа:"},
  {"id": "cu-sv--0012", "section": "service", "who": "reader", "text": "Петре, апостолов основание, / каменю Христовы Церкве, / христианов начало, / паси овцы твоего двора славно: / агнцы твоя сохрани от волков льстивых, / избави стадо твое от напастей лютых, / тя бо молитвенника к Богу неусыпна стяжахом воистинну / и, о тебе хвалящеся, спасаемся вси. Стих:"},
  {"id": "cu-sv--0013", "section": "service", "who": "reader", "text": "Во всю землю изыде вещание их / и в концы вселенныя глаголы их."},
  {"id": "cu-sv--0014", "section": "service", "who": "reader", "text": "Павле, языков ловче, / христиан предстателю, / вселенныя светильниче, / уста немолчна Христа, Живаго Бога, / обтекий, якоже солнце, концы вся / проповеданием Божественныя веры. / Разреши от уз греховных вся восхваляющия тя / и красящияся молитвами твоими. Стих:"},
  {"id": "cu-sv--0015", "section": "service", "who": "reader", "text": "Небеса поведают славу Божию, / творение же руку Его возвещает твердь."},
  {"id": "cu-sv--0016", "section": "service", "who": "reader", "text": "Петре, верховный учениче, Павле, апостолов исполнение, / первии проповедницы, / ныне со дерзновением молитеся к Богу прилежно / и скорую помощь и разрешение бед вкупе низпослите скорбящим нам, / яко да похвалимся верою / и ныне в сени вашей / делы проявляюще покров ваш."},
  {"id": "cu-sv--0017", "section": "service", "who": "reader", "text": "Слава, глас 4. Иоанна монаха: Христос, тя перваго избрав, / Петре, основание веры, / венча тя, Иже всех Владыка тебе предрече: / блажен еси, Симоне вар Иона, / яко плоть и кровь не яви, священнопроповедника Моего сотвори тя, / но Отец Мой, Иже есть на Небесех, / Того моли, Богоблаженне апостоле, / даровати нам велию милость."},
  {"id": "cu-sv--0018", "section": "service", "who": "reader", "text": "И ныне, Богородичен: Избави нас от нужд наших, / Мати Христа Бога, / Рождшая всех Творца, / да вси зовем Ти: / радуйся, едино Предстательство душ наших."},
  {"id": "cu-sv--0019", "section": "service", "who": "reader", "text": "Тропарь, глас 4: Апостолов первопрестольницы / и вселенныя учителие, / Владыку всех молите / мир вселенней даровати / и душам нашим велию милость."},
  {"id": "cu-sv--0020", "section": "service", "who": "reader", "text": "Слава, и ныне, Богородичен: Еже от века утаенное, / и ангелом несведомое таинство, / Тобою, Богородице, сущим на земли явися Бог, / в неслитном соединении воплощаемь, / и крест волею нас ради восприим: / имже воскресив первозданнаго, / спасе от смерти души наша."},
  {"id": "cu-sv--0021", "section": "service", "who": "rubric", "text": "Святых, славных и всехвальных первоверховных апостолов петра и павла"},
  {"id": "cu-sv--0022", "section": "service", "who": "reader", "text": "НА ВЕЛИЦЕЙ ВЕЧЕРНИ"},
  {"id": "cu-sv--0023", "section": "service", "who": "rubric", "text": "По обычном псалме поем:"},
  {"id": "cu-sv--0024", "section": "service", "who": "reader", "text": "Блажен муж:"},
  {"id": "cu-sv--0025", "section": "service", "who": "rubric", "text": "1-й антифон. На"},
  {"id": "cu-sv--0026", "section": "service", "who": "reader", "text": "Господи, воззвах:"},
  {"id": "cu-sv--0027", "section": "service", "who": "rubric", "text": "стихиры на 8, глас 2. Самоподобен. Андрея Пирскаго:"},
  {"id": "cu-sv--0028", "section": "service", "who": "reader", "text": "Киими похвальными венцы / увязем Петра и Павла, / разделенныя телесы / и совокупленныя духом, / Богопроповедников первостоятели? / Оваго убо яко апостолов предначальника, / оваго же яко паче инех трудившася. / Сих бо воистинну достойно безсмертныя славы венцы / венчает Христос Бог наш, / имеяй велию милость."},
  {"id": "cu-sv--0029", "section": "service", "who": "reader", "text": "Киими песненными добротами / воспоем Петра и Павла? / Богоразумия криле, прелетевшия концы / и к Небеси вознесшияся, / руце Евангелия благодати, / нозе истиннаго проповедания, / реки премудрости, / крестныя роги, / имиже демонов бровь Христос низложи, / имеяй велию милость."},
  {"id": "cu-sv--0030", "section": "service", "who": "reader", "text": "Киими духовными песньми / похвалим Петра и Павла? / Безбожия заклавшия незатыкаемая уста, / страшныя Духа мечи, / Рима светлая удобрения, / всея вселенныя питатели, / Новаго Завета Богописанныя скрижали мысленныя, / яже в Сионе Христос возгласи, / имеяй велию милость."},
  {"id": "cu-sv--0031", "section": "service", "who": "reader", "text": "Слава, глас 4. Иоанна монаха: Трикратным вопрошением, / еже: Петре, любиши ли Мя? / трикратное отвержение Христос исправил есть. / Темже и к Тайноведцу Симон: / Господи, вся веси, вся знаеши, / Ты веси, яко люблю Тя. / Темже к нему Спас: / паси овцы Моя, паси избранныя Моя, / паси агнцы Моя, яже Моею кровию снабдех во спасение. / Того моли, Богоблаженне апостоле, / даровати нам велию милость."},
  {"id": "cu-sv--0032", "section": "service", "who": "reader", "text": "И ныне, Богородичен: Иже Тебе ради / богоотец пророк Давид / песненно о Тебе провозгласи, / величия тебе Сотворшему: / предста Царица одесную Тебе. / Тя бо Матерь, Ходатаицу живота показа, / без отца из Тебе вочеловечитися Благоволивый Бог: / да Свой паки обновит образ, истлевший страстьми, / и заблуждшее горохищное обрет овча, / на рамо восприим, к Отцу принесет, / и Своему хотению, с Небесными соединит Силами, / и спасет, Богородице, мiр, / Христос имеяй велию и богатую милость."},
  {"id": "cu-sv--0033", "section": "service", "who": "rubric", "text": "Вход. Прокимен дне. И чтения:"},
  {"id": "cu-sv--0034", "section": "service", "who": "reader", "text": "Соборнаго Послания Петрова чтение (глава 1):"},
  {"id": "cu-sv--0035", "section": "service", "who": "reader", "text": "Братие, благословен Бог и Отец Господа нашего Иисуса Христа, Иже по мнозей Своей милости порождей нас во упование живо воскресением Иисус Христовым от мертвых, в наследие нетленно, и нескверно, и неувядаемо, соблюдено на Небесех вас ради, иже силою Божиею соблюдени верою во спасение, готовое явитися во время последнее. О немже радуйтеся, мало ныне, аще лепо есть, прискорбни бывше в различных напастех, да искушение вашея веры многочестнейше злата гибнуща, огнем же искушена, обрящется в похвалу и честь и славу, во откровении Иисус Христове, Егоже не видевше, любите, и на Негоже ныне не зряще, верующе же, радуетеся радостию неизглаголанною и прославленною, приемлюще кончину вере вашей, спасение душам."},
  {"id": "cu-sv--0036", "section": "service", "who": "reader", "text": "Соборнаго Послания Петрова чтение (глава 1):"},
  {"id": "cu-sv--0037", "section": "service", "who": "reader", "text": "Возлюбленнии, препоясавше чресла помышления вашего, трезвящеся совершенне, уповайте на приносимую вам благодать откровением Иисус Христовым. Яко чада послушания, не преобразующеся первыми неведения вашего похотении, но по звавшему вы Святому, и сами святи во всем житии будите. Зане писано есть: святи будите, яко Аз Свят есмь. И аще Отца называете, нелицемерно судяща комуждо по делу, со страхом жития вашего время жительствуйте, ведяще, яко не истленным сребром или златом избавистеся от суетнаго вашего жития, отцы преданнаго, но честною кровию, яко Агнца непорочна и Пречиста, Христа."},
  {"id": "cu-sv--0038", "section": "service", "who": "reader", "text": "Соборнаго Послания Петрова чтение (глава 2):"},
  {"id": "cu-sv--0039", "section": "service", "who": "reader", "text": "Возлюбленнии, молю, яко пришельцы и странники, огребатися от плотских похотей, яже воюют на душу, житие ваше имуще добро во языцех, да о немже клевещут вас, аки злодеев, от добрых дел видевше, прославят Бога в день просвещения. Повинитеся убо всякому человечу созданию, Господа ради: аще царю, яко преобладающу, аще ли же князем, яко от Него посланным, во отмщение убо злодеем, в похвалу же благотворцем. Яко тако есть воля Божия, благотворящим обуздовати безумных человек невежество, яко свободни, а не яко прикровение имуще злобы свободу, но яко раби Божии. Всех почитайте, братство возлюбите, Бога бойтеся, царя чтите. Раби, повинуйтеся во всяком страсе владыкам, не токмо благим и кротким, но и строптивым. Се бо есть угодно пред Богом, аще совести ради Божия терпит кто скорби, стражда без правды. Кая бо похвала, аще согрешающе, мучими, терпите? Но, аще добро творяще и страждуще, терпите, сие угодно пред Богом. На сие бо и звани бысте, зане и Христос пострада по нас, нам оставль образ, да последуем стопам Его. Иже греха не сотвори, ни обретеся лесть во устех Его. Иже укоряемь, противу не укоряше, стражда, не прещаше, предаяше же судящему праведно. Иже грехи наша Сам вознесе на теле Своем на древо, да, от грех избывше, правдою поживем."},
  {"id": "cu-sv--0040", "section": "service", "who": "reader", "text": "На литии стихиры, глас 2. Самогласны."},
  {"id": "cu-sv--0041", "section": "service", "who": "rubric", "text": "Андрея Иерусалимиты:"},
  {"id": "cu-sv--0042", "section": "service", "who": "reader", "text": "Грядите, собори днесь верных, / благохвальное и красное собрание, / благодати избранныя хитрецы, / Петра и Павла, подобными хвалами венчаем, / яко независтно всем слово всеявше, / с сими и благодать Духа обогатиша, / и, истиннаго винограда суще лозие, / грозд зрел нам возделаша, / веселящ сердца наша. / К нимже откровенным лицем и чистою совестию возопием, глаголюще: / радуйтеся, разорители безсловесных и служителие словесных. / Радуйтеся, всех Творца и Строителя избрания красная. / Радуйтеся, ходатаи благих и отгонителие лестных, / ихже да умолим: / молитеся присно к Зиждителю и Учителю / мир крепкостоятелен миру даровати / и душам нашим велию милость. Арсениево:"},
  {"id": "cu-sv--0043", "section": "service", "who": "reader", "text": "Ученики Христовы и основания Церкве, / истинныя столпы и стены / и трубы Божественныя Христовых учений и страданий, / верховныя Петра и Павла, / яко всего мира предстатели, восхвалим: / сии бо, обтекше широту всея земли, / якоже ралом, всеяша веру / и всем Богоразумие всадиша, / Тройческое являюще Слово. / О, Петре, каменю и основание, / и Павле, сосуде избранный! / Иже и сопряженнии волы Христовы, / вся привлекоша к Богоразумию языки, / грады же и островы, / евреи же паки ко Христу возведоша, / и молят спастися душам нашим. Германово:"},
  {"id": "cu-sv--0044", "section": "service", "who": "reader", "text": "Петре, верховне славных апостол, каменю веры, / и Павле чудне, Святых Церквей вития и светильниче, / Божественному престолу предстояще, / о нас Христу молитеся."},
  {"id": "cu-sv--0045", "section": "service", "who": "reader", "text": "Павле, уста Господня, основание учений, / иногда убо гонитель Иисуса Спаса, / ныне же и первопрестольник апостолов быв, блаженне. / Темже неизглаголанная видел еси, мудре, / даже до третияго небесе возшед, и взывал еси: / приидите со мною, и благих не лишимся."},
  {"id": "cu-sv--0046", "section": "service", "who": "rubric", "text": "Глас 3. Иоанна монаха:"},
  {"id": "cu-sv--0047", "section": "service", "who": "reader", "text": "Вышняго Иерусалима граждане, / камень веры, вития Церкве Христовы, / Тройческая двоица, мира ловцы, / оставльше днесь яже на земли, / отыдоша страданием к Богу / и молятся Ему со дерзновением / спастися душам нашим."},
  {"id": "cu-sv--0048", "section": "service", "who": "reader", "text": "Слава, глас 5. Византиево: Премудрость Божия, Соприсносущное Слово Отчее, / якоже в Евангелиях предрече, многоплодныя лозы / вы есте, всехвальнии апостоли, / иже грозд зрел и красен в ветвех ваших носящии, / егоже, вернии, ядуще, услаждаем вкус к веселию. / Петре, каменю веры, / и Павле, похвало вселенныя, / утвердите стадо, еже стяжасте ученьми вашими."},
  {"id": "cu-sv--0049", "section": "service", "who": "reader", "text": "И ныне, Богородичен: Блажим Тя Богородице Дево, и славим Тя вернии по долгу, град непоколебимый, стену необоримую, твердую Предстательницу, и Прибежище душ наших."},
  {"id": "cu-sv--0050", "section": "service", "who": "reader", "text": "На стиховне стихиры самогласны, глас 1:"},
  {"id": "cu-sv--0051", "section": "service", "who": "rubric", "text": "Андрея Критского:"},
  {"id": "cu-sv--0052", "section": "service", "who": "reader", "text": "Яже по вся грады узы и скорби твоя, / кто скажет, славне апостоле Павле? / Труды, болезни и бдения, / яже во алчбе и жажде злострастия, / яже в зиме и наготе, кошницу и жезлобиения, / каменометания и обхождения, глубины истопления, / позор был еси Ангелов и человеков. / Вся убо претерпел еси о укрепляющем тя Христе, / да мир приобрящеши, о Христе Иисусе, Господе твоем. / Темже молим тя, творящии память твою верно: / непрестанно моли спастися душам нашим. Стих:"},
  {"id": "cu-sv--0053", "section": "service", "who": "reader", "text": "Во всю землю изыде вещание их / и в концы вселенныя глаголы их."},
  {"id": "cu-sv--0054", "section": "service", "who": "reader", "text": "Яже по вся грады вязания и скорби твоя / кто исповесть, славне апостоле? / Или кто представит подвиги и труды твоя, / имиже трудился еси во Евангелии Христове, / да вся приобрящеши и Христу приведеши Церковь? / Но сию проси сохранити доброе твое исповедание, / даже до конечнаго издыхания, / Павле апостоле и учителю Церквей. Стих:"},
  {"id": "cu-sv--0055", "section": "service", "who": "reader", "text": "Небеса поведают славу Божию, / творение же руку Его возвещает твердь."},
  {"id": "cu-sv--0056", "section": "service", "who": "reader", "text": "Светильники великия Церкве, / Петра и Павла восхвалим: / паче бо солнца возсияша на тверди веры / и языки зарями проповедания от неведения возведоша. / Ов убо на кресте пригвождься, / к Небеси шествия творя, / идеже Царствия ключи от Христа прият, / ов же мечем усечен быв, / ко Спасу отшед, / по достоянию ублажаются / и оба Израилю возвещают, / яко на Самаго Господа неправедно руце простре. / Темже молитвами их, Христе Боже наш, / на ны шатающияся низложи / и православных веру утверди, / яко Человеколюбец."},
  {"id": "cu-sv--0057", "section": "service", "who": "reader", "text": "Слава, глас 6. Ефрема Кария: Праздник радостен возсия концем днесь: / всечестная память премудрых апостол и верховных / Петра и Павла, / темже и Рим срадуется, ликовствуя в песнех и пениих. / Празднуем и мы, братие, / всечестный сей день совершивше. / Радуйся, Петре апостоле, / искренний друже твоего Учителя, / Христа, Бога нашего; / радуйся, Павле вселюбезнейший, / и проповедниче веры, и учителю вселенныя; / яко имея дерзновение, / супруже святоизбранный, / Христа, Бога нашего молите / спастися душам нашим."},
  {"id": "cu-sv--0058", "section": "service", "who": "reader", "text": "И ныне, Богородичен: Творец и Избавитель мой, Пречистая, / Христос Господь, из Твоих ложесн прошед, / в мя Оболкийся, первыя клятвы Адама свободи. / Темже Ти, Всечистая, / яко Божии Матери же и Деве, / воистинну вопием немолчно: / радуйся Ангельски, радуйся, Владычице, / Предстательство и Покрове / и Спасение душ наших."},
  {"id": "cu-sv--0059", "section": "service", "who": "rubric", "text": "На благословении хлебов тропарь апостолов, дважды, и"},
  {"id": "cu-sv--0060", "section": "service", "who": "reader", "text": "Богородице Дево:"},
  {"id": "cu-sv--0061", "section": "service", "who": "rubric", "text": "единожды, и чтение."},
  {"id": "cu-sv--0062", "section": "service", "who": "reader", "text": "Тропарь, глас 4: Апостолов первопрестольницы / и вселенныя учителие, / Владыку всех молите / мир вселенней даровати / и душам нашим велию милость."},
  {"id": "cu-sv--0063", "section": "service", "who": "rubric", "text": "Святых, славных и всехвальных первоверховных апостолов петра и павла"},
  {"id": "cu-sv--0064", "section": "service", "who": "reader", "text": "НА УТРЕНИ На"},
  {"id": "cu-sv--0065", "section": "service", "who": "reader", "text": "Бог Господь:"},
  {"id": "cu-sv--0066", "section": "service", "who": "reader", "text": "Тропарь Апостолов, глас 4, дважды:"},
  {"id": "cu-sv--0067", "section": "service", "who": "reader", "text": "Апостолов первопрестольницы / и вселенныя учителие, / Владыку всех молите / мир вселенней даровати / и душам нашим велию милость."},
  {"id": "cu-sv--0068", "section": "service", "who": "reader", "text": "Слава, и ныне, Богородичен: Еже от века утаенное, / и ангелом несведомое таинство, / Тобою, Богородице, сущим на земли явися Бог, / в неслитном соединении воплощаемь, / и крест волею нас ради восприим: / имже воскресив первозданнаго, / спасе от смерти души наша."},
  {"id": "cu-sv--0069", "section": "service", "who": "reader", "text": "По 1-й кафизме седален, глас 8. Подобен: Премудрости:"},
  {"id": "cu-sv--0070", "section": "service", "who": "reader", "text": "Глубину ловления оставль, / с Небесе прием от Отца Божественное откровение Слова воплощения, / и со дерзновением верно вопиял еси Зиждителю Твоему: / Божия Тя вем Сына Единосущна. / Темже по достоянию воистинну показался еси камень веры / и ключарь благодати, Петре апостоле. / Моли Христа Бога грехов оставление даровати / празднующим любовию святую память твою."},
  {"id": "cu-sv--0071", "section": "service", "who": "reader", "text": "Слава, глас 1. Подобен: Камени запечатану:"},
  {"id": "cu-sv--0072", "section": "service", "who": "reader", "text": "Церковнаго каменя, всехвальнаго Петра, и поборника Павла, / мирскую мрежу, достойно восхвалим, вернии, яко имуща ключи Небесныя: / от них бо просветися вселенная верою Тройческою. / Слава Прославльшему вас, / слава Укрепльшему вы, / слава Даровавшему вас ради жизнь вечную."},
  {"id": "cu-sv--0073", "section": "service", "who": "reader", "text": "И ныне, Богородичен: Руце Твои Божественнии, / имиже Создателя понесла еси, / Дево Пресвятая, воплощшагося благостынею, / простерши, умоли Его избавити нас от искушений, и страстей, и бед, / хвалящих Тя любовию и вопиющих: / слава Всельшемуся в Тя, / слава Прошедшему из Тебе, / слава Избавльшему нас рождеством Твоим."},
  {"id": "cu-sv--0074", "section": "service", "who": "reader", "text": "По 2-й кафизме седален, глас 8. Подобен: Премудрости:"},
  {"id": "cu-sv--0075", "section": "service", "who": "reader", "text": "С Небесе звание от Христа приим, явился еси проповедник Света, / всех благодати озарил еси ученьми: / закона бо служение писмене изстругав, верным облистал еси разум Духа. / Темже и в третие небо достойне взятся превыспренно, / и в рай достигл еси, Павле апостоле. / Моли Христа Бога согрешений оставление даровати / празднующим любовию святую память твою."},
  {"id": "cu-sv--0076", "section": "service", "who": "reader", "text": "Слава, глас 4. Подобен: Явился еси днесь:"},
  {"id": "cu-sv--0077", "section": "service", "who": "reader", "text": "Светолучными сиянии, якоже звезды, земныя концы просвещаете учении святыя проповеди, / Небеснии таинницы, Господни апостоли."},
  {"id": "cu-sv--0078", "section": "service", "who": "reader", "text": "И ныне, Богородичен: Теплое заступление сущим в бедах, и Помощницу нашу, / и к Богу пременение, Еюже тли избавихомся, / Богородицу, вернии, ублажаем."},
  {"id": "cu-sv--0079", "section": "service", "who": "reader", "text": "Величание: Величаем вас, апостоли Христовы Петре и Павле, / весь мир ученьми своими просветившия / и вся концы / ко Христу приведшия."},
  {"id": "cu-sv--0080", "section": "service", "who": "rubric", "text": "Святым апостолом общий"},
  {"id": "cu-sv--0081", "section": "service", "who": "reader", "text": "Величаем тя, / апостоле Христов [имярек]"},
  {"id": "cu-sv--0082", "section": "service", "who": "reader", "text": ", / и чтим болезни и труды твоя, / имиже трудился еси / во благовестии Христове."},
  {"id": "cu-sv--0083", "section": "service", "who": "reader", "text": "Псалом избранный: Небеса поведают славу Божию, творение же руку Его возвещает твердь. / Исповедят Небеса чудеса Твоя, Господи. / Вместо отец Твоих быша сынове Твои. / Поставиши я князи по всей земли. / Бог богов Господь глагола и призва землю. / От восток солнца до запад хвально Имя Господне. / Осветиша молния Его вселенную, / возвестиша Небеса правду Его, / и видеша вси людие славу Его. / Князи Иудовы владыки их. / Воцарися Бог над языки. / Бог прославляемь в совете святых. / Велий и страшен есть над всеми окрестными Его. / Рцыте во языцех, яко Господь воцарися. / Возвестите во языцех славу Его, во всех людех чудеса Его. / Во всю землю изыде вещание их, / и в концы вселенныя глаголы их. / Покори люди нам и языки под ноги наша. / Велий Господь наш и велия крепость Его. / Той даст силу и державу людем Своим: благословен Бог."},
  {"id": "cu-sv--0084", "section": "service", "who": "reader", "text": "Слава, и ныне: Аллилуия: Трижды."},
  {"id": "cu-sv--0085", "section": "service", "who": "reader", "text": "По полиелеи седален, глас 8. Подобен: Премудрости:"},
  {"id": "cu-sv--0086", "section": "service", "who": "reader", "text": "Верховныя явльшияся от ученик, великия светильники и светлыя, / Петра да восхвалим и премудраго Павла: / огнем бо Божественнаго просиявшия Духа, мглу прелести попалиша всю, / темже и Вышняго Царствия оружницы достойне показашася и благодати сопрестольницы. / Сего ради вопием: / апостоли Христа Бога, прегрешений оставление испросите / празднующим любовию святую память вашу."},
  {"id": "cu-sv--0087", "section": "service", "who": "reader", "text": "Слава, и ныне, Богородичен: Яко Всенепорочная Невеста Творцу, яко Неискусомужная Мати Избавителя, / приятелище яко сущи Утешителя, Препетая, / беззаконию мя суща скверное обителище и бесом игралище в разуме бывша, / потщися от тех злодейства мя избавити / и светлое жилище добродетелей соверши, Светоносная Нетленная, / отжени облак страстей и Вышняго причастия сподоби / и света невечерняго молитвами Твоими."},
  {"id": "cu-sv--0088", "section": "service", "who": "rubric", "text": "Степенна, 1-й антифон 4-го гласа."},
  {"id": "cu-sv--0089", "section": "service", "who": "reader", "text": "Прокимен, глас 4: Во всю землю изыде вещание их / и в концы вселенныя глаголы их. Стих:"},
  {"id": "cu-sv--0090", "section": "service", "who": "reader", "text": "Небеса поведают славу Божию, творение же руку Его возвещает твердь."},
  {"id": "cu-sv--0091", "section": "service", "who": "reader", "text": "Всякое дыхание: Стих:"},
  {"id": "cu-sv--0092", "section": "service", "who": "reader", "text": "Хвалите Бога во святых Его:"},
  {"id": "cu-sv--0093", "section": "service", "who": "reader", "text": "Евангелие от Иоанна, зачало 67:"},
  {"id": "cu-sv--0094", "section": "service", "who": "reader", "text": "Во время оно, явися Иисус учеником Своим, востав от мертвых. И глагола Симону Петру: Симоне Ионин, любиши ли Мя паче сих? Глагола Ему: ей, Господи, Ты веси, яко люблю Тя. Глагола ему: паси агнцы Моя. Глагола ему паки второе: Симоне Ионин, любиши ли Мя? Глагола ему: ей, Господи, Ты веси, яко люблю Тя. Глагола ему: паси овцы Моя. Глагола ему третие: Симоне Ионин, любиши ли Мя? Оскорбе же Петр, яко рече ему третие, любиши ли Мя; и глагола Ему: Господи, Ты вся веси, Ты веси, яко люблю Тя. Глагола ему Иисус: паси овцы Моя. Аминь, аминь, глаголю тебе, егда бе юн, поясашеся сам, и хождаше, аможе хотяше, егда же состареешися и воздежеши руце твои, и ин тя пояшет, и ведет, аможе не хощеши. Сие же рече, назнаменуя, коею смертию прославит Бога. И сия рек, глагола ему: иди по Мне. Обращься же Петр, виде ученика, егоже любляше Иисус, во след идуща, иже и возлеже на вечери на перси Его, и рече: Господи, кто есть предаяй Тя? Сего видев Петр, глагола Иисусови: Господи, сей же что? Глагола ему Иисус: аще хощу, да той пребывает, дондеже прииду, что к тебе? Ты по Мне гряди. Изыде же слово се в братию, яко ученик той не умрет; и не рече ему Иисус, яко не умрет, но аще хощу тому пребывати, дондеже прииду, что к тебе? Сей есть ученик свидетельствуяй о сих, иже и написа сия, и вем, яко истинно есть свидетельство его. Суть же и ина многа, яже сотвори Иисус, яже аще по единому писана бывают, ни самому мню всему миру вместити пишемых книг. Аминь."},
  {"id": "cu-sv--0095", "section": "service", "who": "reader", "text": "По 50-м псалме стихира, глас 6. Самогласна:"},
  {"id": "cu-sv--0096", "section": "service", "who": "reader", "text": "Благочестия истинныя проповедники / и Церкве пресветлыя звезды / песньми похвальными почтим, / Петра, каменя веры, / и Павла, истиннаго учителя и таинника Христова. / Сии бо истинное слово всеявше в сердца верных, / всем плодоносие дарующа, / и молят Христа Бога / спастися душам нашим."},
  {"id": "cu-sv--0097", "section": "service", "who": "rubric", "text": "Канона два. Творение Иоанна Дамаскина. Первый святаго апостола Петра, глас 4, со ирмосом на 8, ирмос по дважды, тропари на 6."},
  {"id": "cu-sv--0098", "section": "service", "who": "reader", "text": "Песнь 1. Ирмос:"},
  {"id": "cu-sv--0099", "section": "service", "who": "reader", "text": "Несть Тебе подобен, / препрославленный Господи, / рукою бо крепкою избавил еси люди, / яже стяжал еси, Человеколюбче."},
  {"id": "cu-sv--0100", "section": "service", "who": "reader", "text": "Верховнейшаго апостолов днесь, яко первозваннаго Христова, / богодохновенными песньми достойно воспоим."},
  {"id": "cu-sv--0101", "section": "service", "who": "reader", "text": "Тя предвечный проуведев, предустави, всеблаженне Петре, / яко предстателя Своея Церкве и первопрестольника."},
  {"id": "cu-sv--0102", "section": "service", "who": "reader", "text": "Ни плоть, ниже кровь тебе, но Отец вдохну / Христа богословити, Сына истиннаго Бога Вышняго, апостоле. Богородичен:"},
  {"id": "cu-sv--0103", "section": "service", "who": "reader", "text": "Гору святую, превышнее носило, / Матерь Божию и Деву истинную по рождестве воспоем."},
  {"id": "cu-sv--0104", "section": "service", "who": "reader", "text": "Ин канон святаго апостола Павла, тропари на 6, глас 8."},
  {"id": "cu-sv--0105", "section": "service", "who": "reader", "text": "Песнь 1. Ирмос:"},
  {"id": "cu-sv--0106", "section": "service", "who": "reader", "text": "Посеченный несекомаго пресече, / и виде солнце землю, юже не виде, / лютаго врага вода потопи, / и непроходимое пройде Израиль, / песнь же воспевашеся: / Господеви поим, славно бо прославися."},
  {"id": "cu-sv--0107", "section": "service", "who": "reader", "text": "Якоже сущая нарицая не сущая Христос Божественным разумом, Павле всеблаженне, / Той из матерня чрева тя избра / понести пред языки Божественное Его Имя, еже паче всякаго имене: / славно бо прославися."},
  {"id": "cu-sv--0108", "section": "service", "who": "reader", "text": "Будущее возвещая тебе сияние благочестия, Павле, / и лести очищение, / Христос явлься на горе молниезрачен, / очи убо помрачает плотския, душевныя же вразумляет Тройческим разумом: / славно бо прославися."},
  {"id": "cu-sv--0109", "section": "service", "who": "reader", "text": "Обрезание убо совершая осмодневное и ревнитель отеческих, Павле, преданий, / от семене еврейска, колена Вениаминова, / по закону же фарисей явлься, / вменил еси вся уметы и Христа приобрел еси: / славно бо прославися. Богородичен:"},
  {"id": "cu-sv--0110", "section": "service", "who": "reader", "text": "Чистая Мати Бога Вседержителя, от царскаго колена, Владычице, израстши / и едина Бога, всеми царствующаго, рождшая плотию паче естества, / от бед мя спаси, Сыну Твоему поюща: / славно бо прославися. Катавасия:"},
  {"id": "cu-sv--0111", "section": "service", "who": "reader", "text": "Отверзу уста моя:"},
  {"id": "cu-sv--0112", "section": "service", "who": "reader", "text": "Песнь 3. Ирмос:"},
  {"id": "cu-sv--0113", "section": "service", "who": "reader", "text": "Не мудростию, и силою, и богатством хвалимся, / но Тобою, Отчею Ипостасною мудростию, Христе: / несть бо свят, паче Тебе, Человеколюбче."},
  {"id": "cu-sv--0114", "section": "service", "who": "reader", "text": "Тя, блаженна, сладкая уста Христа Бога и сокровище твердо Царствия показаша. / Темже воспеваем тя, Петре апостоле."},
  {"id": "cu-sv--0115", "section": "service", "who": "reader", "text": "На камени твоего Богословия водрузи Владыка Иисус Церковь непреклонну, / в нейже тя, апостоле Петре, славим."},
  {"id": "cu-sv--0116", "section": "service", "who": "reader", "text": "Яко пребольши Ангел Петр в телеси: / во светлом бо пришествии сего / Христос Бог судию же и соседателя быти рече. Богородичен:"},
  {"id": "cu-sv--0117", "section": "service", "who": "reader", "text": "Неискусобрачная, Бога плотию рождшая, / страстными прилоги преклоненна мя утверди: / несть бо, Чистая, разве Тебе, помощницы. Ин, ирмос:"},
  {"id": "cu-sv--0118", "section": "service", "who": "reader", "text": "Ты еси утверждение / притекающих к Тебе, Господи, / Ты еси свет омраченных, / и поет Тя дух мой."},
  {"id": "cu-sv--0119", "section": "service", "who": "reader", "text": "Ты камень основания верным душам положился еси многоценен, / краеуголен Спаса и Господа."},
  {"id": "cu-sv--0120", "section": "service", "who": "reader", "text": "Павле всеблаженне, / на основании твоем, молися, добродетелей всехвальных наздатися светлости."},
  {"id": "cu-sv--0121", "section": "service", "who": "reader", "text": "Всегда мертвость Иисусову на твоем теле совершенно, Павле, обносяй, / сподобился еси истинныя жизни. Богородичен:"},
  {"id": "cu-sv--0122", "section": "service", "who": "reader", "text": "Тя вси стяжахом прибежище и стену нашу, христиане, / Тя славословим немолчно, Безневестная."},
  {"id": "cu-sv--0123", "section": "service", "who": "reader", "text": "Ипакои, глас 8: Кая темница не име тебе юзника? / Кая же Церковь не имать тя витию? / Дамаск великомудрствует о тебе, Павле, веде бо тя запята светом; / Рим, твою кровь приемый, и той хвалится, / но и Тарс множае радуется и любит, почитая твои пелены. / Петре, веры каменю, Павле, похвало вселенныя, / от Рима сошедшеся, утвердите нас."},
  {"id": "cu-sv--0124", "section": "service", "who": "reader", "text": "Песнь 4. Ирмос:"},
  {"id": "cu-sv--0125", "section": "service", "who": "reader", "text": "Сей Бог наш, от Девы воплощся / и естество обожив, / Егоже воспевающе, вопием: / слава силе Твоей, Господи."},
  {"id": "cu-sv--0126", "section": "service", "who": "reader", "text": "Человеком ловца тя, якоже обеща Христос, содела Божественна Своея Церкве, / первому вручив кормила."},
  {"id": "cu-sv--0127", "section": "service", "who": "reader", "text": "Тобою умоляемь Жизнодавец Иисус, / вязати же и решити давый тебе власть, Петре, да будет ми милостив."},
  {"id": "cu-sv--0128", "section": "service", "who": "reader", "text": "Христово Царствие отверсти прилежно молися, Петре, / Божественную твою память верою несумненною чтущим. Богородичен:"},
  {"id": "cu-sv--0129", "section": "service", "who": "reader", "text": "Госпоже Всепетая, Богородительнице, / моя помышления Твоими молитвами очистивши, / покажи мя благоплодна, Мати всех Бога. Ин, ирмос:"},
  {"id": "cu-sv--0130", "section": "service", "who": "reader", "text": "Всел еси на кони, апостолы Твоя, Господи, / и приял еси рукама Твоима узды их, / и спасение быстъ еждение Твое / верно поющим: / слава силе Твоей, Господи."},
  {"id": "cu-sv--0131", "section": "service", "who": "reader", "text": "Вседе, якоже лев, яровидно погубляя Христову Церковь, Савл иногда, / ят же быв Божественным гласом Агнца Божия, Егоже гоняше, / стадо яко пастырю вручает."},
  {"id": "cu-sv--0132", "section": "service", "who": "reader", "text": "Хотяй просветити вселенную омрачается, / Анания же к сему послася, душевное же просвещение даяй и телесное / от Божественнаго явления, сосуд избран показав того."},
  {"id": "cu-sv--0133", "section": "service", "who": "reader", "text": "Павлом достойно Дамаск напояется: / от сего бо, якоже от рая иногда, / вод Божественных сей произыде великий источник / и упои всю Богоразумием независтно землю. Богородичен:"},
  {"id": "cu-sv--0134", "section": "service", "who": "reader", "text": "Низложи сильныя со престол Господь, Дева и Мати якоже рече, / алчущия же Божественных благ исполни, верою зовущия: / слава силе Твоей, Господи."},
  {"id": "cu-sv--0135", "section": "service", "who": "reader", "text": "Песнь 5. Ирмос:"},
  {"id": "cu-sv--0136", "section": "service", "who": "reader", "text": "Стяжавый ны, избранныя люди / Кровию Твоею, Господи, / Твой мир даждь нам, / во единомыслии сохраняя стадо Твое."},
  {"id": "cu-sv--0137", "section": "service", "who": "reader", "text": "Иже от любве приим дерзновение к Богу, / достойно чудим бываше ловец и невежда, / чудодействуя преславно благодатию."},
  {"id": "cu-sv--0138", "section": "service", "who": "reader", "text": "Не злато Тебе ради, ни сребро, Христе, / Божественный Твой апостол, но добродетель стяжав, / чудес обогатися силою."},
  {"id": "cu-sv--0139", "section": "service", "who": "reader", "text": "Исправляхуся стопы и глезне хромых, действенным твоим глаголом: / Божественным бо Духом совершахуся преславныя вещи. Богородичен:"},
  {"id": "cu-sv--0140", "section": "service", "who": "reader", "text": "Воплотися Бог по ипостаси, Чистая, из Тебе плотию соединяемь, / пребыв неизменен, по Божественному существу безплотен. Ин, ирмос:"},
  {"id": "cu-sv--0141", "section": "service", "who": "reader", "text": "Просвети нас повелении Твоими, Господи, / и мышцею Твоею высокою / Твой мир подаждь нам, / Человеколюбче."},
  {"id": "cu-sv--0142", "section": "service", "who": "reader", "text": "Ты истинную избрал еси, Павле, похвалу, / Крест Царя Христа присно нося, / якоже победу, апостоле."},
  {"id": "cu-sv--0143", "section": "service", "who": "reader", "text": "Тебе еже жити, Христос, и еже умрети, приобретение изрядно: / любовию бо сраспялся еси Распеншемуся нас ради, Павле преславне."},
  {"id": "cu-sv--0144", "section": "service", "who": "reader", "text": "Радуешися воистинну о Господе, Павле честный, изшед из телесе / и отшед ко Христу, Жизнодавцу Богу. Богородичен:"},
  {"id": "cu-sv--0145", "section": "service", "who": "reader", "text": "Моли присно Сына Твоего и Бога нашего, / Неискусобрачная Марие Чистая, / послати нам, верным, милость."},
  {"id": "cu-sv--0146", "section": "service", "who": "reader", "text": "Песнь 6. Ирмос:"},
  {"id": "cu-sv--0147", "section": "service", "who": "reader", "text": "В ките, Христе, тридневновав, Иона / прописа Тя, Безсмертнаго, яко мертва волею / в сердце земнем тридневновавша."},
  {"id": "cu-sv--0148", "section": "service", "who": "reader", "text": "Якоже древле, Христе, десницею Твоею по воде пеша ходяща Петра спасл еси, / и мене, потопляема бурею лютых напастей, спаси, яко Милосерд."},
  {"id": "cu-sv--0149", "section": "service", "who": "reader", "text": "Оставил еси, о Петре, не сущая, / и сущая достигл еси, якоже некий купец, / и яве уловил еси бисер, Христа, многоценный."},
  {"id": "cu-sv--0150", "section": "service", "who": "reader", "text": "Искушати безумно покусившияся Духа Пресвятаго, Петре, умертвил еси: / Егоже богословил еси ты первее, / яве исповедав Бога, всеблаженне. Богородичен:"},
  {"id": "cu-sv--0151", "section": "service", "who": "reader", "text": "Всякаго вышша существа Слово Божие родила еси, воплощенно нам, / темже Богородицу Тя устнами же и душею проповедаем. Ин, ирмос:"},
  {"id": "cu-sv--0152", "section": "service", "who": "reader", "text": "Молитву пролию ко Господу / и Тому возвещу печали моя, / яко зол душа моя исполнися / и живот мой аду приближися, / и молюся, яко Иона: / от тли, Боже, возведи мя."},
  {"id": "cu-sv--0153", "section": "service", "who": "reader", "text": "Вся пренебрег красная мира, / уязвлен Владычнею любовию и общаго спасения желанием, / свидетельствовати тому изволив, о Павле блаженне, / и ныне о вселенней молися."},
  {"id": "cu-sv--0154", "section": "service", "who": "reader", "text": "Яко изрядный Владыце подобник / и в Того одеян, Павле, воистинну всем был еси всяк, / да вся приобрящеши и спасеши люди, / и спасл еси яко воистинну, Христу уловив концы."},
  {"id": "cu-sv--0155", "section": "service", "who": "reader", "text": "Достойно тебе дарова Христос житие, апостоле Павле, на Небесех: / пребывающаго бо зде не возжелал еси града, блаженне, / верен служитель быв и строитель таин Его. Богородичен:"},
  {"id": "cu-sv--0156", "section": "service", "who": "reader", "text": "Призре на Тя Господь, мое обновляя существо, яко Силен, / величия сотворь, Богородительнице, якоже рекла еси, Всенепорочная, / и спасе мя Тобою из тли Бог мой, яко Милосерд."},
  {"id": "cu-sv--0157", "section": "service", "who": "reader", "text": "Кондак, глас 2: Твердыя и Боговещанныя проповедатели, / верх апостолов Твоих, Господи, / приял еси в наслаждение благих Твоих и покой: / болезни бо онех и смерть приял еси паче всякаго всеплодия, / Едине, сведый сердечная. Икос:"},
  {"id": "cu-sv--0158", "section": "service", "who": "reader", "text": "Уясни мой язык, Спасе мой, разширив моя уста / и исполнив я, умили сердце мое, / да, яже глаголю, последую и, яже убо учу, сотворю первее: / всяк бо творя и уча, рече, сей велик есть. / Аще бо глаголю, и не творю, яко медь звенящая вменюся; / темже рещи ми подобная и творити полезная даруй, / Едине, сведый сердечная."},
  {"id": "cu-sv--0159", "section": "service", "who": "reader", "text": "Песнь 7. Ирмос:"},
  {"id": "cu-sv--0160", "section": "service", "who": "reader", "text": "В начале Безначальное Слово, / со Отцем и Духом, Сын Единородный, / благословен еси, и превозносимый / Боже отец наших."},
  {"id": "cu-sv--0161", "section": "service", "who": "reader", "text": "Милостивному, Божественным промыслом Христовым наказуемь, / подобитися попущен был еси, прежде страсти, Петре, / отвержения подпасти волнению."},
  {"id": "cu-sv--0162", "section": "service", "who": "reader", "text": "Тебе Христос, первозванному и зело возлюбленному, / яко председателю благославну апостолов, первому является, воскрес от гроба."},
  {"id": "cu-sv--0163", "section": "service", "who": "reader", "text": "Твое трикратное, еже прежде страсти, исцеляя отвержение, Владыка / трикратным боговещанным, Петре, вопрошением утверждает любовь."},
  {"id": "cu-sv--0164", "section": "service", "who": "reader", "text": "Еже ко Христу, Петре, любления, / предлагал еси свидетеля и Всевидящаго яко Бога Слова, / темже и любимое вручает тебе стадо. Богородичен:"},
  {"id": "cu-sv--0165", "section": "service", "who": "reader", "text": "Яже во утробе Превечное, / от Отца возсиявшее Бога Слово плотию заченшую, / вси ублажаем, яко Матерь всех Бога. Ин, ирмос:"},
  {"id": "cu-sv--0166", "section": "service", "who": "reader", "text": "На поле Деире / иногда мучитель пещь постави на мучение богоносных, / в нейже три отроки песнословяху Единаго Бога, / троично воспеваху, глаголюще: / отцев Боже, благословен еси."},
  {"id": "cu-sv--0167", "section": "service", "who": "reader", "text": "Бысть, Христе, печать и венец апостолов Твоих, / иже напоследок званный времен, тщанием же всех превозшед, / с нимже людие церковнии поют Тебе: / отец наших Боже, благословен еси."},
  {"id": "cu-sv--0168", "section": "service", "who": "reader", "text": "Аще и гонив первее Церковь Твою Павел узник, / но премину древнюю дерзость Твоею ревностию последи. / Собра бо, Христе, языки, зовущия: / отец наших Боже, благословен еси."},
  {"id": "cu-sv--0169", "section": "service", "who": "reader", "text": "Ты из Иерусалима проповедав всем Евангелие, / объят же окрест всю землю, Павле, / даже до конец Иллирика, уча, взывал еси: / отец наших Боже, благословен еси."},
  {"id": "cu-sv--0170", "section": "service", "who": "reader", "text": "Во ужасе взят быв, третие достигл еси Небо, пребогате, / и, услышав неизглаголанная словеса, вопиеши: / слава превышнему Отцу и Сыну, / сияние же сопрестольно испытающаго яве Духа Божия глубины. Богородичен:"},
  {"id": "cu-sv--0171", "section": "service", "who": "reader", "text": "Якоже на руно дождь, на Тя сниде, Дево, Христос Бог, / и Плотоносец из Тебе пройде, соединяя прежде разстоящая, / мир на земли и на Небеси даруя: / отец наших Боже, благословен еси."},
  {"id": "cu-sv--0172", "section": "service", "who": "reader", "text": "Песнь 8. Ирмос:"},
  {"id": "cu-sv--0173", "section": "service", "who": "reader", "text": "Всяческая носяй неприступною Твоею силою, Христе, / преподобныя Твоя отроки в пламени оросил еси, зовущия: / благословите, вся дела Господня, Господа."},
  {"id": "cu-sv--0174", "section": "service", "who": "reader", "text": "Воздежут твои руце и ко кресту тя препояшут, – / Владыка предрек, Петре, повелевает последовати зовущу: / благословите, вся дела Господня, Господа."},
  {"id": "cu-sv--0175", "section": "service", "who": "reader", "text": "Благодати словом Енея, убо разслабленна люте, / Тавифу же умершую, чудодействуя, воскресил еси, зовущия: / благословите, вся дела Господня, Господа."},
  {"id": "cu-sv--0176", "section": "service", "who": "reader", "text": "Иже Петру языки очищены поведав, Христе, / духовною зарею и мне помышления очисти, зовущу: / благословите, вся дела Господня, Господа. Богородичен:"},
  {"id": "cu-sv--0177", "section": "service", "who": "reader", "text": "Всесвятая Дево, Яже Бога Слова рождшая плотию, / души моея мрак Твоими молитвами отгнавши, просвети, взывающа: / благословите, вся дела Господня, Господа. Ин, ирмос:"},
  {"id": "cu-sv--0178", "section": "service", "who": "reader", "text": "На горе святей прославльшася / и в купине огнем Приснодевы Моисеови тайну явльшаго, / Господа пойте / и превозносите во вся веки."},
  {"id": "cu-sv--0179", "section": "service", "who": "reader", "text": "Срастворися любовию Твоею Павел, добрым же изменением изступи: / не себе бо живяше славный, / имяше же, Щедре, живуща Тя в себе во вся веки."},
  {"id": "cu-sv--0180", "section": "service", "who": "reader", "text": "Ты обручил еси, якоже невесту, представити Жениху Христу Церковь: / невестовождь бо сея показался еси, Павле Богоносе. / Темже тя славит во вся веки."},
  {"id": "cu-sv--0181", "section": "service", "who": "reader", "text": "Подвизался еси добрым подвигом / и, скончав течение твое законно, сокровище веры соблюл еси. / Темже венцев, Павле, сподобился еси правды. Богородичен:"},
  {"id": "cu-sv--0182", "section": "service", "who": "reader", "text": "Радуйся, престоле огнезрачный Господень; / радуйся, Невесто Неневестная, Дево, / радуйся, облаче, Солнца возсиявшая правды, / Егоже превозносим во вся веки."},
  {"id": "cu-sv--0183", "section": "service", "who": "reader", "text": "Песнь 9. Ирмос:"},
  {"id": "cu-sv--0184", "section": "service", "who": "reader", "text": "Тя, преславную Невесту и Всесвятую Богородицу, / Зиждителя рождшую невидимых же и всех видимых, / песньми величаем."},
  {"id": "cu-sv--0185", "section": "service", "who": "reader", "text": "Твоя преизящная благодать славится достойно, / сени бо твоей страсти немощных, Петре, отгоняющей, / темже тя величаем."},
  {"id": "cu-sv--0186", "section": "service", "who": "reader", "text": "Мечтаньми Симона волхва богоборца взята к воздушней высоте, / низложив неизглаголанною Божественною силою, / Петр ублажается."},
  {"id": "cu-sv--0187", "section": "service", "who": "reader", "text": "Согрешений разрешение молитвами твоими подаждь, / просвещение же сердца и веселие духа поющим память твою, апостоле."},
  {"id": "cu-sv--0188", "section": "service", "who": "reader", "text": "Твоя вся исполнена славы, освящения же и чудес: / словеса, мощи, персть и верою, Петре, покланяемыя и любовию Божественныя вериги. Богородичен:"},
  {"id": "cu-sv--0189", "section": "service", "who": "reader", "text": "Твое имя Плод чрева содея ликовника песнь пети Тебе, / Иже радость рождши, / велегласно – радуйся – провещавающа. Ин, ирмос:"},
  {"id": "cu-sv--0190", "section": "service", "who": "reader", "text": "Уставы прешла еси естества, / Содетеля заченши и Господа, / и дверь спасения мирови была еси. / Тем Тя, Богородице, / непрестанно величаем."},
  {"id": "cu-sv--0191", "section": "service", "who": "reader", "text": "Твоим покланяемся веригам, яже за Христа, яко злодей, носил еси, / язвы же, Павле, облобызаем, / яже на славнем твоем и победоноснем носиши телеси."},
  {"id": "cu-sv--0192", "section": "service", "who": "reader", "text": "Ныне разрешился еси, апостоле, ко Иже тобою непрестанно Желаемому, / с Нимже яко служитель водворяяся, / непрестанными мольбами твоя рабы к себе привлецы."},
  {"id": "cu-sv--0193", "section": "service", "who": "reader", "text": "Ныне никакоже в гаданиих, ниже в зерцале Христос тебе зрим есть, / лицем же паче зрится к лицу, / совершенне тебе разум открывая Божества. Богородичен:"},
  {"id": "cu-sv--0194", "section": "service", "who": "reader", "text": "Ты, Пресвятая Богомати, похвала Христовых апостолов была еси, / мучеников же слава и пророков основание. / Темже, вернии, Тя вси достодолжно величаем."},
  {"id": "cu-sv--0195", "section": "service", "who": "reader", "text": "Светилен. Подобен: Жены, услышите:"},
  {"id": "cu-sv--0196", "section": "service", "who": "reader", "text": "Апостолов вси верх воспоем, Петра и Павла Божественныя, / вселенныя светильники, проповедники веры, богословныя трубы, учений сказатели, / церковныя столпы и разорители лести."},
  {"id": "cu-sv--0197", "section": "service", "who": "reader", "text": "Слава, и ныне, Богородичен: Велико и преславно рождества Твоего таинство, Богорадованная Отроковице и Богомати Дево, / пророцы проповедаша, апостоли научиша, мученицы исповедаша, / Ангели же воспевают и человецы покланяются."},
  {"id": "cu-sv--0198", "section": "service", "who": "reader", "text": "На хвалитех стихиры на 4, глас 4. Подобен: Званный свыше:"},
  {"id": "cu-sv--0199", "section": "service", "who": "reader", "text": "С небесе благодать прием, / егда вопрошение учеником Спас дванадесяточисленным рече апостолом: / кого Мя глаголют человецы быти? / Тогда убо лучший апостолов Петр, / богословствуя, отвеща, ясно возопив: / Ты еси Христос, Живаго Бога Сын. / Темже достойно ублажается, / яко свыше прием откровение, / вязати же и решити праведно прием."},
  {"id": "cu-sv--0200", "section": "service", "who": "reader", "text": "Иже от Отца явлься Божие Слово, – / кого Мя непщуете? – вопрошающу Христу. / Ты Живаго Отца Сын, – / яко всем уста богогласуя, / абие возопил еси, / темже и блажен еси, Симоне вар Иона, / возмездие приял еси. / Ибо славит Бог Сего верно славящия, / и к восприятию богатно призывает, / и каменя тебе непостыдна, / Церкви водружение и основание положи."},
  {"id": "cu-sv--0201", "section": "service", "who": "reader", "text": "Свыше зван быв, / а не от человек, / егда земная тьма помрачи очи телесныя, / нечестия обличая сетование, / тогда Небесный свет облиста мысленнии очи, / благочестия открывая красоту. / Темже познал еси изводящаго свет из тьмы, / Христа Бога нашего, / Егоже моли / спасти и просветити души наша."},
  {"id": "cu-sv--0202", "section": "service", "who": "reader", "text": "Христопроповедник сый, / крестную похвалу носяй, / ты многорачительную Божественную любовь, / яко зрящих связующую к Желаемому, / воистинну паче всех проразсудил еси. / Темже и узник прозвался еси Христов, / напастей неудобство, / яко сладчайшее пищи всякия, изволивый, / и честныя кончины разрешения сподобился еси, / живый Владыце твоему, / Егоже моли / спасти и просветити души наша."},
  {"id": "cu-sv--0203", "section": "service", "who": "reader", "text": "Слава, глас 6. Космы монаха: Всечестный апостолов приспе праздник Церкви Христове, / ходатайствующий спасение всем нам. / Тайно убо восплескавше, к сим рцем: / радуйтеся, светильницы сущим во тьме, / мысленнаго Солнца зари облистающии. / Радуйтеся, Петре и Павле, / учений Божественных основания незыблема, / друзи Христовы, сосуди честнии. / Приидите посреди нас невидимо, / сподобляюще даров невещественных / ваш праздник восхваляющих песньми."},
  {"id": "cu-sv--0204", "section": "service", "who": "reader", "text": "И ныне: Богородице, ты еси Лоза истинная, / возрастившая нам Плод Живота, / Тебе молимся, / молися, Владычице, со святыми апостолы, / помиловати души наша."},
  {"id": "cu-sv--0205", "section": "service", "who": "rubric", "text": "Славословие великое. И отпуст."},
  {"id": "cu-sv--0206", "section": "service", "who": "rubric", "text": "Святых, славных и всехвальных первоверховных апостолов петра и павла"},
  {"id": "cu-sv--0207", "section": "service", "who": "reader", "text": "НА ЛИТУРГИИ"},
  {"id": "cu-sv--0208", "section": "service", "who": "rubric", "text": "Блаженны, от канона апостола Петра, песнь 3-я, на 4, и Павла, песнь 6-я, на 4."},
  {"id": "cu-sv--0209", "section": "service", "who": "reader", "text": "Тропарь, глас 4: Апостолов первопрестольницы / и вселенныя учителие, / Владыку всех молите / мир вселенней даровати / и душам нашим велию милость."},
  {"id": "cu-sv--0210", "section": "service", "who": "reader", "text": "Кондак, глас 2: Твердыя и Боговещанныя проповедатели, / верх апостолов Твоих, Господи, / приял еси в наслаждение благих Твоих и покой: / болезни бо онех и смерть приял еси паче всякаго всеплодия, / Едине, сведый сердечная."},
  {"id": "cu-sv--0211", "section": "service", "who": "reader", "text": "Прокимен, глас 8: Во всю землю изыде вещание их / и в концы вселенныя глаголы их. Стих:"},
  {"id": "cu-sv--0212", "section": "service", "who": "reader", "text": "Небеса поведают славу Божию, творение же руку Его возвещает твердь."},
  {"id": "cu-sv--0213", "section": "service", "who": "reader", "text": "Апостол к Коринфяном, зачало 193: Братие, о немже аще дерзает кто, [несмысленно глаголю:] дерзаю и аз. Евреи ли суть? И аз. Израильте ли суть? И аз. Семя Авраамле ли суть? И аз. Служителие ли Христовы суть? [Не в мудрости глаголю,] паче аз. В трудех множае, в ранах преболе, в темницах излиха, в смертех многащи. От иудей пятькраты четыридесять, разве единыя, приях. Трищи палицами биен бых, единою каменьми наметан бых; трикраты корабль опровержеся со мною; нощь и день во глубине сотворих. В путных шествиих множицею; беды в реках, беды от разбойник, беды от сродник, беды от язык, беды во градех, беды в пустыни, беды в мори, беды во лжебратии. В труде и подвизе, во бдениих множицею, во алчбе и жажди, в пощениих многащи, в зиме и наготе. Кроме внешних, нападение еже по вся дни, и попечение всех церквей. Кто изнемогает, и не изнемогаю; кто соблазняется, и аз не разжизаюся? Аще хвалитися ми подобает, яже о немощи моей похвалюся. Бог и Отец Господа нашего Иисуса Христа весть, Сый благословен во веки, яко не лгу. В Дамасце языческий князь Арефы царя стрежаше Дамаск град, яти мя хотя, и оконцем в кошнице свешен бых по стене, и избегох из руку его. Похвалитися же не пользует ми: прииду бо в видения и откровения Господня. Вем человека о Христе, прежде лет четыринадесяти, [аще в теле, не вем, аще ли кроме тела, не вем, Бог весть,] восхищена бывша таковаго до третияго Небесе. И вем такова человека, [аще в теле, или кроме тела, не вем, Бог весть,] яко восхищен бысть в рай, и слыша неизреченны глаголы, ихже не леть есть человеку глаголати. О таковем похвалюся, о себе же не похвалюся, токмо о немощех моих. Аще бо восхощу похвалитися, не буду безумен, истину бо реку, щажду же, да не како кто вознепщует о мне паче, еже видит мя, или слышит что от мене. И за премногая откровения да не превозношуся, дадеся ми пакостник плоти, аггел сатанин, да ми пакости деет, да не превозношуся. О сем трикраты Господа молих, да отступит от мене. И рече ми: довлеет ти благодать Моя: сила бо Моя в немощи совершается. Сладце убо похвалюся паче в немощех моих, да вселится в мя сила Христова."},
  {"id": "cu-sv--0214", "section": "service", "who": "reader", "text": "Аллилуия, глас 1: Исповедят Небеса чудеса Твоя, Господи. Стих:"},
  {"id": "cu-sv--0215", "section": "service", "who": "reader", "text": "Бог прославляемь в совете святых."},
  {"id": "cu-sv--0216", "section": "service", "who": "reader", "text": "Евангелие от Матфея, зачало 67: Во время оно, пришед Иисус во страны Кесарии Филипповы, вопрошаше ученики Своя, глаголя: кого Мя глаголют человецы быти, Сына Человеческаго? Они же реша: ови убо Иоанна Крестителя, инии же Илию, друзии же Иеремию, или единаго от пророк. Глагола им Иисус: вы же кого Мя глаголете быти? Отвещав же Симон Петр рече: Ты еси Христос, Сын Бога живаго. И отвещав Иисус рече ему: блажен еси, Симоне, вар Иона, яко плоть и кровь не яви тебе, но Отец Мой, иже на Небесех. И Аз же тебе глаголю, яко ты еси Петр, и на сем камени созижду Церковь Мою, и врата адова не одолеют ей. И дам ти ключи Царства Небеснаго, и еже аще свяжеши на земли, будет связано на Небесех, и еже аще разрешиши на земли, будет разрешено на Небесех."},
  {"id": "cu-sv--0217", "section": "service", "who": "reader", "text": "Причастен: Во всю землю изыде вещание их / и в концы вселенныя глаголы их."},
  {"id": "cu-sv--0218", "section": "service", "who": "rubric", "text": "Рядовый Апостол и Евангелие вычитаем прежде. На трапезе утешение братии великое. Аще случится сей праздник святых апостол в среду или в пяток, ямы рыбу и пием вино."},
  {"id": "cu-sv--0219", "section": "service", "who": "rubric", "text": "Подобает ведати: Яко аще случится праздник святых апостол в неделю, предваряются вся воскресная."},
  {"id": "cu-sv--0220", "section": "service", "who": "reader", "text": "Молитва О преславнии апостоли Петре и Павле, души за Христа предавшии и кровию вашею пажить Его удобрившии! Услышите чад ваших молитвы и воздыхания, сердцем сокрушенным ныне приносимыя. Се бо беззаконьми омрачихомся и того ради бедами, якоже тучами, обложихомся, елея же добраго жития обнищахом зело. О сильнии! Понесите немощи наша, не отлучайтеся духом от нас, да не разлучимся вконец от любве Божия, но крепким заступлением вашим нас защитите, да помилует Господь всех нас молитв ваших ради, да истребит же рукописание безмерных грехов наших и да сподобит со всеми святыми блаженнаго Царствия и брака Агнца Своего, Емуже честь, и слава, и благодарение, и поклонение во веки веков. Аминь."},
];

